INSERT INTO "Question" ("id", "sourceId", "questionEn", "questionFr", "answersEn", "answersFr", "correctIndex", "category", "difficulty", "createdAt") VALUES
    (gen_random_uuid()::text, 'gen-eaae32ded197003c', 'According to legend, which famous Roman general invented coq au vin after receiving a rooster from Vercingetorix?', 'Selon la légende, quel célèbre général romain a inventé le coq au vin après avoir reçu un coq de la part de Vercingétorix ?', '["Nero", "Augustus", "Mark Antony", "Julius Caesar"]'::jsonb, '["Néron", "Auguste", "Marc Antoine", "Jules César"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-07bf768be16e832c', 'In 2010, the gastronomic meal of the French was added to the UNESCO heritage list alongside the cuisine of which other country?', 'En 2010, le repas gastronomique des Français a été inscrit à l''UNESCO en même temps que la cuisine de quel autre pays ?', '["Spain", "Japan", "Mexico", "Italy"]'::jsonb, '["L''Espagne", "Le Japon", "Le Mexique", "L''Italie"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-abf96a95112cd7a0', 'In which ancient city, the ancestor of Marseille, did bouillabaisse originate?', 'Dans quelle ville antique, ancêtre de Marseille, la bouillabaisse a-t-elle vu le jour ?', '["Lugdunum", "Nemausus", "Lutetia", "Massalia"]'::jsonb, '["Lugdunum", "Nemausus", "Lutèce", "Massalia"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-0ffbcb4021eec99e', 'Which French chef codified haute cuisine in the 20th century, becoming the modern benchmark for gastronomy?', 'Quel chef français a codifié la grande cuisine au XXe siècle, devenant la référence moderne de la gastronomie ?', '["Marie-Antoine Carême", "Guillaume Tirel", "Auguste Escoffier", "François Pierre de La Varenne"]'::jsonb, '["Marie-Antoine Carême", "Guillaume Tirel", "Auguste Escoffier", "François Pierre de La Varenne"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5d3fbcfd94a3e285', 'Which marine animal was considered a fish and thus eaten during Lent in the Middle Ages?', 'Quel animal marin était considéré comme un poisson et donc consommé pendant le Carême au Moyen Âge ?', '["The seal", "The penguin", "The otter", "The dolphin"]'::jsonb, '["Le phoque", "Le manchot", "La loutre", "Le dauphin"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-891031d3a17ea6a2', 'In the Middle Ages, spices like pepper and cinnamon were cheap products consumed by everyone.', 'Au Moyen Âge, les épices comme le poivre et la cannelle étaient des produits bon marché consommés par tout le monde.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-adf8127d6388d7d7', 'For which event was the Eiffel Tower originally built?', 'Pour quel événement la tour Eiffel a-t-elle été construite à l''origine ?', '["The 1900 Olympic Games", "The first airplane flight", "The 1937 World''s Fair", "The 1889 World''s Fair"]'::jsonb, '["Les Jeux olympiques de 1900", "Le premier vol d''avion", "L''Exposition universelle de 1937", "L''Exposition universelle de 1889"]'::jsonb, 3, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b51443519e946c77', 'What was the original name of the Eiffel Tower during its design phase?', 'Quel était le nom initial de la tour Eiffel lors de sa conception ?', '["The spire of Paris", "The iron tower", "The 300-meter tower", "The Gustave tower"]'::jsonb, '["La flèche de Paris", "La tour de fer", "La tour de 300 mètres", "La tour Gustave"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9dc57943195e4aa5', 'The Eiffel Tower held the title of the world''s tallest structure until the construction of the Chrysler Building in New York.', 'La tour Eiffel a détenu le titre de plus haute structure du monde jusqu''à la construction du Chrysler Building à New York.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-48495b0e15417618', 'The construction of the Eiffel Tower took less than a year.', 'La construction de la tour Eiffel a duré moins d''un an.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5c9127c62728c13e', 'What natural phenomenon causes the Eiffel Tower to slightly change size between summer and winter?', 'Quel phénomène naturel fait varier légèrement la taille de la tour Eiffel entre l''été et l''hiver ?', '["Soil erosion", "Metal oxidation", "Thermal expansion", "Wind pressure"]'::jsonb, '["L''érosion des sols", "L''oxydation du métal", "La dilatation thermique", "La pression du vent"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9c0002f0078e74c0', 'Approximately how many steps are there in the Eiffel Tower to reach the very top?', 'Environ combien de marches compte la tour Eiffel pour atteindre le sommet ?', '["1 665", "2 400", "850", "3 100"]'::jsonb, '["1 665", "2 400", "850", "3 100"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-547b708005ecb386', 'Which of these monarchs did NOT live at the Palace of Versailles as their main residence?', 'Lequel de ces monarques n''a PAS vécu au château de Versailles comme résidence principale ?', '["Louis XV", "Louis XVI", "Henri IV", "Louis XIV"]'::jsonb, '["Louis XV", "Louis XVI", "Henri IV", "Louis XIV"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d12b3bd8d56afb88', 'What was the original purpose of the first building constructed by Louis XIII at Versailles?', 'Quelle était la fonction initiale du premier bâtiment construit par Louis XIII à Versailles ?', '["A royal theater", "A military fortress", "A religious monastery", "A hunting lodge"]'::jsonb, '["Un théâtre royal", "Une forteresse militaire", "Un monastère religieux", "Un pavillon de chasse"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1161f23fb357da79', 'Approximately how many rooms does the Palace of Versailles contain?', 'Environ combien de pièces le château de Versailles contient-il ?', '["10 000", "4 500", "800", "2 300"]'::jsonb, '["10 000", "4 500", "800", "2 300"]'::jsonb, 3, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c47b98936e3c868d', 'Louis XIV became King of France when he was a teenager.', 'Louis XIV est devenu roi de France alors qu''il était adolescent.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-67954170a70b55b4', 'Which of these is considered a terrestrial planet in our solar system?', 'Laquelle de ces planètes est considérée comme une planète tellurique du Système solaire ?', '["Neptune", "Jupiter", "Mars", "Saturn"]'::jsonb, '["Neptune", "Jupiter", "Mars", "Saturne"]'::jsonb, 2, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d511173b1e8324bb', 'Approximately what percentage of the solar system''s total mass is contained within the Sun?', 'Quel pourcentage de la masse totale du Système solaire est contenu dans le Soleil ?', '["75%", "90%", "50%", "99.85%"]'::jsonb, '["75 %", "90 %", "50 %", "99,85 %"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a7199b74f8167a6d', 'Only Saturn has a system of rings around it.', 'Seule la planète Saturne possède un système d''anneaux.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b91a64d8bdf6374d', 'Which of these is classified as an ''ice giant'' rather than a ''gas giant''?', 'Laquelle de ces planètes est classée comme une « géante de glace » plutôt qu''une « géante gazeuse » ?', '["Neptune", "Jupiter", "Mars", "Saturn"]'::jsonb, '["Neptune", "Jupiter", "Mars", "Saturne"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4ae4ea8b7ec8501b', 'In which galaxy is our solar system located?', 'Dans quelle galaxie se trouve notre Système solaire ?', '["Messier 87", "The Milky Way", "Triangulum", "Andromeda"]'::jsonb, '["Messier 87", "La Voie lactée", "Triangle", "Andromède"]'::jsonb, 1, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-49f6a68da7192bfd', 'What type of star is the Sun?', 'Quel est le type d''étoile du Soleil ?', '["Red giant", "Blue supergiant", "White dwarf", "Yellow dwarf"]'::jsonb, '["Géante rouge", "Supergéante bleue", "Naine blanche", "Naine jaune"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6067927197b45215', 'Which planet is a notable exception because it rotates in a retrograde direction?', 'Quelle planète est une exception notable car elle tourne dans le sens rétrograde ?', '["Mars", "Neptune", "Venus", "Mercury"]'::jsonb, '["Mars", "Neptune", "Vénus", "Mercure"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e50c687d4c893071', 'Some moons in our solar system are larger than the planet Mercury.', 'Certaines lunes de notre Système solaire sont plus grandes que la planète Mercure.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5c6ffb1c20b21a23', 'The point in an orbit where a body is closest to the Sun is called the aphelion.', 'Le point d''une orbite où un corps est le plus proche du Soleil est appelé l''aphélie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a6f0356605d68fb6', 'According to Kepler''s laws, what is the approximate shape of the orbits of objects around the Sun?', 'Selon les lois de Kepler, quelle est la forme approximative des orbites des objets autour du Soleil ?', '["Parabolas", "Squares", "Circles", "Ellipses"]'::jsonb, '["Des paraboles", "Des carrés", "Des cercles", "Des ellipses"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5e2c74b800a1045e', 'An adult human body is made up of approximately 60% water.', 'Le corps d''un adulte est composé d''environ 60 % d''eau.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-71a23bf1ab083733', 'If fully unraveled, the DNA within a single human cell would be about 10 meters long.', 'Si on le déroulait, l''ADN d''une seule cellule humaine mesurerait environ 10 mètres.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-688c7ae1047c0675', 'Which public holiday is the only one in France that is mandatory and paid for employees?', 'Quel est le seul jour férié en France obligatoirement chômé et payé pour les salariés ?', '["May 1st", "July 14th", "November 11th", "December 25th"]'::jsonb, '["Le 1er mai", "Le 14 juillet", "Le 11 novembre", "Le 25 décembre"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-33bb151e4eaebd1f', 'In which year did July 14th officially become a public holiday in France?', 'En quelle année le 14 juillet est-il officiellement devenu un jour férié en France ?', '["1880", "1922", "1947", "1789"]'::jsonb, '["1880", "1922", "1947", "1789"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-971fd045a8f56656', 'Which historical event does the French national holiday on July 14th commemorate?', 'Quel événement historique est commémoré par la fête nationale française du 14 juillet ?', '["The Fête de la Fédération", "The birth of the Republic", "The signing of the Concordat", "The end of World War I"]'::jsonb, '["La Fête de la Fédération", "La naissance de la République", "La signature du Concordat", "La fin de la Première Guerre mondiale"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5ee2501849b20d1b', 'Which of these days is a public holiday in Alsace and Moselle, but not in the rest of France?', 'Lequel de ces jours est férié en Alsace-Moselle, mais pas dans le reste de la France ?', '["The Epiphany", "The Assumption", "Saint Nicholas Day", "Saint Stephen''s Day (December 26)"]'::jsonb, '["L''Épiphanie", "L''Assomption", "La Saint-Nicolas", "Le lendemain de Noël (26 décembre)"]'::jsonb, 3, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fe78e06e0df0fe8d', 'Which of the Seven Wonders of the Ancient World is still standing today?', 'Quelle est la seule merveille du monde antique qui existe encore aujourd''hui ?', '["The Colossus of Rhodes", "The Temple of Artemis", "The Pyramids of Giza", "The Lighthouse of Alexandria"]'::jsonb, '["Le colosse de Rhodes", "Le temple d''Artémis", "Les pyramides de Gizeh", "Le phare d''Alexandrie"]'::jsonb, 2, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3715f029320f441f', 'It is possible that the Hanging Gardens of Babylon never actually existed.', 'Il est possible que les jardins suspendus de Babylone n''aient jamais réellement existé.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ac5b706562b75b9a', 'The Colossus of Rhodes was a giant statue representing which deity?', 'Le colosse de Rhodes était une statue géante représentant quelle divinité ?', '["Poseidon", "Helios", "Zeus", "Apollo"]'::jsonb, '["Poséidon", "Hélios", "Zeus", "Apollon"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-595a56a697770e3b', 'The Temple of Artemis is located in modern-day Greece.', 'Le temple d''Artémis est situé dans la Grèce actuelle.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-54fa9e3a87d829ec', 'Where was the statue of Zeus, one of the Seven Wonders, located?', 'Où se situait la statue de Zeus, l''une des sept merveilles du monde ?', '["Athens", "Rhodes", "Olympia", "Sparta"]'::jsonb, '["Athènes", "Rhodes", "Olympie", "Sparte"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-0887b03ac15f8285', 'Which famous pyramid is considered the oldest and most complex of the Giza site?', 'Quelle célèbre pyramide est considérée comme la plus ancienne et la plus complexe du site de Gizeh ?', '["Sneferu", "Menkaure", "Khafre", "Khufu"]'::jsonb, '["Snefrou", "Mykérinos", "Khephren", "Khéops"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-79b8cb40b41193b4', 'In which city is the European Central Bank located?', 'Dans quelle ville se situe le siège de la Banque centrale européenne ?', '["Paris", "Berlin", "Frankfurt", "Brussels"]'::jsonb, '["Paris", "Berlin", "Francfort", "Bruxelles"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b9e4b4191e57d50b', 'What was the name of the European currency unit that preceded the euro?', 'Quel était le nom de l''unité de compte européenne qui a précédé l''euro ?', '["Lira", "Franc", "ECU", "Mark"]'::jsonb, '["Lire", "Franc", "ECU", "Mark"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-08a8113832e97129', 'All euro coins have a common European side and a side specific to the issuing country.', 'Toutes les pièces en euro possèdent une face européenne commune et une face spécifique au pays émetteur.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-34646f6ce2fbf9f4', 'What do the designs on euro banknotes represent?', 'Que représentent les dessins figurant sur les billets en euro ?', '["Bridges, doors, and windows", "Famous historical figures", "European landscapes", "National flags"]'::jsonb, '["Des ponts, portes et fenêtres", "Des personnages historiques", "Des paysages européens", "Des drapeaux nationaux"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-863e86c3a8972f58', 'Which banknote was discontinued by the European Central Bank to fight against illegal activities?', 'Quel billet a été supprimé par la Banque centrale européenne pour lutter contre les activités illicites ?', '["200 euros", "500 euros", "1000 euros", "100 euros"]'::jsonb, '["200 euros", "500 euros", "1000 euros", "100 euros"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-74a128087efd0a61', 'The creation of the euro was officially decided during the signing of which treaty?', 'La création de l''euro a été officiellement décidée lors de la signature de quel traité ?', '["Treaty of Maastricht", "Treaty of Nice", "Treaty of Lisbon", "Treaty of Rome"]'::jsonb, '["Traité de Maastricht", "Traité de Nice", "Traité de Lisbonne", "Traité de Rome"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ba5a12daea458a67', 'From which plant is chocolate made?', 'À partir de quelle plante fabrique-t-on le chocolat ?', '["Cacao tree", "Coffee tree", "Vanilla plant", "Sugar cane"]'::jsonb, '["Cacaoyer", "Caféier", "Vanillier", "Canne à sucre"]'::jsonb, 0, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ee7273e2cd040399', 'From which language does the word ''chocolate'' originate?', 'De quelle langue provient le mot ''chocolat'' ?', '["Maya", "Latin", "Nahuatl", "Spanish"]'::jsonb, '["Maya", "Latin", "Nahuatl", "Espagnol"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c0c5c8237b42f3a8', 'What did the ancient Mayas sometimes use as currency?', 'Qu''utilisaient parfois les anciens Mayas comme monnaie ?', '["Gold coins", "Corn flour", "Cocoa beans", "Chili peppers"]'::jsonb, '["Pièces d''or", "Farine de maïs", "Des fèves de cacao", "Piments"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
