    (gen_random_uuid()::text, 'gen-3b33c36f371fd278', 'Which country is considered the original home of the coffee plant?', 'Quel pays est considéré comme le berceau du caféier ?', '["Ethiopia", "Colombia", "Brazil", "Vietnam"]'::jsonb, '["Éthiopie", "Colombie", "Brésil", "Vietnam"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-25be82018fbd0f98', 'According to popular legend, the first person to discover the effects of coffee was a goat herder.', 'Selon la légende la plus répandue, la première personne à avoir découvert les effets du café était un berger.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-07504dcf858d908c', 'After water, what is the most consumed beverage in the world?', 'Après l''eau, quelle est la boisson la plus consommée au monde ?', '["Tea", "Orange juice", "Milk", "Coffee"]'::jsonb, '["Le thé", "Le jus d''orange", "Le lait", "Le café"]'::jsonb, 0, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e694dba33cab363f', 'True or false: An herbal tea (tisane) contains tea leaves.', 'Vrai ou faux : Une tisane contient des feuilles de thé.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-7536fe9c514d3875', 'What did the Scottish botanist Robert Fortune famously smuggle out of China in 1848?', 'Qu''est-ce que le botaniste écossais Robert Fortune a fait sortir clandestinement de Chine en 1848 ?', '["Silk worms", "Tea plants", "Porcelain secrets", "Opium seeds"]'::jsonb, '["Des vers à soie", "Des plants de thé", "Des secrets de porcelaine", "Des graines d''opium"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-50e70fe941b09c5e', 'Which two ingredients give Coca-Cola its name?', 'Quels sont les deux ingrédients qui donnent son nom au Coca-Cola ?', '["Coca leaf and kola nut", "Cocoa bean and cola nut", "Cocoa bean and coffee nut", "Coca leaf and coffee bean"]'::jsonb, '["La feuille de coca et la noix de kola", "La fève de cacao et la noix de kola", "La fève de cacao et le grain de café", "La feuille de coca et le grain de café"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-445d73cccfe4f73f', 'Who invented the precursor to Coca-Cola, called ''French Wine Coca''?', 'Qui a inventé l''ancêtre du Coca-Cola, nommé le « French Wine Coca » ?', '["Frank Robinson", "Asa Griggs Candler", "Joseph Jacobs", "John Pemberton"]'::jsonb, '["Frank Robinson", "Asa Griggs Candler", "Joseph Jacobs", "John Pemberton"]'::jsonb, 3, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5eac045cb0ae8724', 'In the early 20th century, Coca-Cola replaced the cocaine in its recipe with caffeine.', 'Au début du XXe siècle, Coca-Cola a remplacé la cocaïne présente dans sa recette par de la caféine.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6ccf2ebb18ffec42', 'In which French city did the first shipment of Coca-Cola arrive in 1919?', 'Dans quelle ville française est arrivé le premier envoi de Coca-Cola en 1919 ?', '["Lyon", "Marseille", "Bordeaux", "Paris"]'::jsonb, '["Lyon", "Marseille", "Bordeaux", "Paris"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6f335825120085be', 'Coca-Cola is the original creator of the modern image of Santa Claus in red and white.', 'Coca-Cola est le créateur original de l''image moderne du Père Noël en rouge et blanc.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-aa153a9f59c2dc21', 'What is the original meaning of the name ''Lego'' in Danish?', 'Que signifie le nom « Lego » en danois ?', '["Build fast", "Plastic brick", "Happy child", "Play well"]'::jsonb, '["Construis vite", "Brique plastique", "Enfant heureux", "Joue bien"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9bc15c7e6176c66e', 'What was the original profession of Ole Kirk Christiansen, the founder of Lego?', 'Quel était le métier d''origine d''Ole Kirk Christiansen, le fondateur de Lego ?', '["Toy designer", "Carpenter", "Plastic engineer", "School teacher"]'::jsonb, '["Designer de jouets", "Charpentier", "Ingénieur en plastique", "Instituteur"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-70273e5622c04751', 'Lego minifigures have been included in sets since the very beginning of the company in 1932.', 'Les figurines Lego sont incluses dans les boîtes depuis la création de l''entreprise en 1932.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a54ca6f8338b9e2e', 'In which country did the first Legoland theme park open?', 'Dans quel pays a ouvert le premier parc Legoland ?', '["United Kingdom", "Denmark", "Germany", "United States"]'::jsonb, '["Royaume-Uni", "Danemark", "Allemagne", "États-Unis"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ea4e80d02f75e7c8', 'Which two brothers founded the studio that would become The Walt Disney Company?', 'Quels sont les deux frères fondateurs du studio qui deviendra The Walt Disney Company ?', '["Walt and Roy Disney", "Roy and Ub Disney", "Walt and Elias Disney", "Walt and Charles Disney"]'::jsonb, '["Walt et Roy Disney", "Roy et Ub Disney", "Walt et Elias Disney", "Walt et Charles Disney"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9e970df597f6c007', 'Which iconic animated character was created by Walt Disney and Ub Iwerks in 1928?', 'Quel personnage emblématique a été créé par Walt Disney et Ub Iwerks en 1928 ?', '["Goofy", "Oswald the Lucky Rabbit", "Mickey Mouse", "Donald Duck"]'::jsonb, '["Dingo", "Oswald le lapin chanceux", "Mickey Mouse", "Donald Duck"]'::jsonb, 2, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-eda6133fd34dc525', 'Which of these major studios did Disney acquire in 2006?', 'Lequel de ces studios majeurs a été racheté par Disney en 2006 ?', '["Lucasfilm", "20th Century Fox", "Marvel", "Pixar"]'::jsonb, '["Lucasfilm", "20th Century Fox", "Marvel", "Pixar"]'::jsonb, 3, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c43520c5673c7db1', 'Before Mickey Mouse became a success, which character did Disney produce for Charles B. Mintz?', 'Avant le succès de Mickey Mouse, quel personnage Disney produisait-il pour Charles B. Mintz ?', '["Oswald the Lucky Rabbit", "Goofy", "Donald Duck", "Alice"]'::jsonb, '["Oswald le lapin chanceux", "Dingo", "Donald Duck", "Alice"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-991407bb0b5a0600', 'Snow White and the Seven Dwarfs was the very first animated feature film produced by Disney.', 'Blanche-Neige et les Sept Nains est le tout premier long métrage d''animation produit par Disney.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b70565f21af8622f', 'In France, December 26th is a public holiday throughout the entire country.', 'En France, le 26 décembre est un jour férié sur tout le territoire national.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a66963a4c8839acb', 'Which historical figure is credited with popularizing the nativity scene (crèche) in the 13th century?', 'Quel personnage historique a popularisé la crèche de Noël au XIIIe siècle ?', '["Saint Nicholas", "Saint Benedict", "Saint Peter", "Saint Francis of Assisi"]'::jsonb, '["Saint Nicolas", "Saint Benoît", "Saint Pierre", "Saint François d''Assise"]'::jsonb, 3, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6fad2fc8e38f7cb6', 'When is Halloween celebrated?', 'À quelle date Halloween est-elle célébrée ?', '["December 25th", "October 1st", "November 1st", "October 31st"]'::jsonb, '["Le 25 décembre", "Le 1er octobre", "Le 1er novembre", "Le 31 octobre"]'::jsonb, 3, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fcac204516ae45b3', 'The legend of the Jack-o''-lantern comes from Ireland.', 'La légende de la lanterne Jack-o''-lantern est originaire d''Irlande.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-23723002f4d43c26', 'What vegetable was originally used for Jack-o''-lanterns in Europe before pumpkins?', 'Quel légume était utilisé à l''origine pour les lanternes en Europe, avant la citrouille ?', '["Turnips", "Potatoes", "Beets", "Carrots"]'::jsonb, '["Le navet", "La pomme de terre", "La betterave", "La carotte"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b24ca99786e48e48', 'Halloween is considered the successor to which ancient Celtic festival?', 'Halloween est considérée comme l''héritière de quelle ancienne fête celtique ?', '["Samain", "Beltane", "Imbolc", "Lughnasadh"]'::jsonb, '["La Samain", "Beltaine", "Imbolc", "Lugnasad"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-06205d1d4ca27b58', 'What is the literal meaning of the word ''carnival''?', 'Que signifie littéralement le mot « carnaval » ?', '["Street festival", "Farewell to winter", "Removing meat", "Masked parade"]'::jsonb, '["Fête de rue", "Adieu à l''hiver", "Enlever la viande", "Défilé masqué"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2181f73db648fbe2', 'Which of these musical styles is traditionally associated with the Carnival in Brazil?', 'Lequel de ces styles musicaux est traditionnellement associé au carnaval au Brésil ?', '["Kompa", "Samba", "Conga", "Huayno"]'::jsonb, '["Kompa", "Samba", "Conga", "Huayno"]'::jsonb, 1, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-33f532340f830d34', 'The Notting Hill Carnival is a traditional event that has existed in London since the Middle Ages.', 'Le carnaval de Notting Hill est un événement traditionnel qui existe à Londres depuis le Moyen Âge.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-547928dbc9a83126', 'Which famous style of comedy theater evolved from the comic plays performed during urban carnivals?', 'Quel célèbre style de théâtre comique a évolué à partir des pièces jouées lors des carnavals urbains ?', '["Commedia dell''arte", "Vaudeville", "Burlesque", "Farce"]'::jsonb, '["Commedia dell''arte", "Vaudeville", "Burlesque", "Farce"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a46a50ce0db01b9b', 'On average, what fraction of a human life is spent sleeping?', 'En moyenne, quelle fraction d''une vie humaine passe-t-on à dormir ?', '["One third", "One half", "One tenth", "One quarter"]'::jsonb, '["Un tiers", "La moitié", "Un dixième", "Un quart"]'::jsonb, 0, 'General Knowledge', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a90520991830f638', 'Who was the mathematician and Albert Einstein''s first wife, whom he met at the Zurich Polytechnic?', 'Quelle mathématicienne était la première épouse d''Albert Einstein, rencontrée à l''École polytechnique de Zurich ?', '["Ada Negri", "Elsa Einstein", "Pauline Koch", "Mileva Marić"]'::jsonb, '["Ada Negri", "Elsa Einstein", "Pauline Koch", "Mileva Marić"]'::jsonb, 3, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9c5b9bda06d466b8', 'Which major scientific and military project did Albert Einstein help initiate with his letter to President Roosevelt?', 'Quel projet scientifique et militaire majeur Albert Einstein a-t-il contribué à lancer avec sa lettre au président Roosevelt ?', '["The Manhattan Project", "The Enigma Project", "The Cold War Initiative", "The Apollo Program"]'::jsonb, '["Le projet Manhattan", "Le projet Enigma", "L''initiative de la guerre froide", "Le programme Apollo"]'::jsonb, 0, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-202de6ce4a589836', 'Which artist''s workshop did Leonardo da Vinci join as an apprentice in Florence?', 'Dans quel atelier d''artiste Léonard de Vinci a-t-il été apprenti à Florence ?', '["Botticelli", "Andrea del Verrocchio", "Domenico Ghirlandaio", "Le Pérugin"]'::jsonb, '["Botticelli", "Andrea del Verrocchio", "Domenico Ghirlandaio", "Le Pérugin"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f73e5b9333d7f5b5', 'Leonardo da Vinci worked as a mapmaker for Cesare Borgia.', 'Léonard de Vinci a travaillé comme cartographe pour César Borgia.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4da277352a6d41b7', 'In which Italian region was Leonardo da Vinci born?', 'Dans quelle région italienne Léonard de Vinci est-il né ?', '["Lazio", "Veneto", "Tuscany", "Lombardy"]'::jsonb, '["Latium", "Vénétie", "Toscane", "Lombardie"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-208321ac98fffc8c', 'What was the profession of Leonardo da Vinci''s father, Piero?', 'Quel était le métier de Piero, le père de Léonard de Vinci ?', '["Painter", "Notary", "Architect", "Merchant"]'::jsonb, '["Peintre", "Notaire", "Architecte", "Marchand"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1436bbbe7854e982', 'Who was the general manager of the White Star Line who initiated the Titanic project?', 'Qui était le directeur général de la White Star Line à l''origine du projet Titanic ?', '["Edward Smith", "Robert Ballard", "Joseph Bruce Ismay", "Thomas Andrews"]'::jsonb, '["Edward Smith", "Robert Ballard", "Joseph Bruce Ismay", "Thomas Andrews"]'::jsonb, 2, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e0b46318e8fdd050', 'Approximately how many rivets were used to hold the Titanic''s hull plates together?', 'Environ combien de rivets ont été utilisés pour maintenir les tôles de la coque du Titanic ?', '["3 million", "5 million", "1 million", "10 million"]'::jsonb, '["3 millions", "5 millions", "1 million", "10 millions"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-7dee51c903000b2a', 'What was the name of the first artificial satellite launched by the Soviet Union in 1957?', 'Quel était le nom du premier satellite artificiel lancé par l''Union soviétique en 1957 ?', '["Vostok 1", "Soyuz 1", "Sputnik 1", "Luna 1"]'::jsonb, '["Vostok 1", "Soyouz 1", "Spoutnik 1", "Luna 1"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9cc00b7b4d2b7e3d', 'In which ocean did the Apollo 11 capsule land upon its return to Earth?', 'Dans quel océan la capsule d''Apollo 11 a-t-elle amerri lors de son retour sur Terre ?', '["Indian Ocean", "Pacific Ocean", "Atlantic Ocean", "Arctic Ocean"]'::jsonb, '["Océan Indien", "Océan Pacifique", "Océan Atlantique", "Océan Arctique"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-cca6ff4f03af7d60', 'What does the Nepali name for Everest, ''Sagarmatha'', translate to in French?', 'Que signifie littéralement le nom népalais de l''Everest, « Sagarmatha » ?', '["Holy mountain", "Head of the sky", "Mother of the winds", "Goddess of the peaks"]'::jsonb, '["Montagne sainte", "La tête du ciel", "Mère des vents", "Déesse des sommets"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-94553ead40a5c0f5', 'In which 1928 animated film did Mickey Mouse make his official debut with synchronized sound?', 'Dans quel film d''animation de 1928 Mickey Mouse fait-il ses débuts officiels avec du son synchronisé ?', '["Steamboat Willie", "Oswald the Lucky Rabbit", "Alice Comedies", "Silly Symphonies"]'::jsonb, '["Steamboat Willie", "Oswald le lapin chanceux", "Alice Comedies", "Silly Symphonies"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-19a9ac02c14a6053', 'Disney was the first client of the company Hewlett-Packard.', 'Disney a été le tout premier client de l''entreprise Hewlett-Packard.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-91214d8a54471bd2', 'What was the name of the new Coca-Cola formula released in the 1980s that caused a commercial disaster?', 'Quel était le nom de la nouvelle formule de Coca-Cola lancée dans les années 1980 qui fut un fiasco commercial ?', '["Coca-Cola Classic", "New Coke", "Coca-Cola Zero", "Coca-Cola Gold"]'::jsonb, '["Coca-Cola Classic", "New Coke", "Coca-Cola Zero", "Coca-Cola Gold"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-30587ac9f1991960', 'Which emperor began the construction of a great wall of ''ten thousand leagues'' following the unification of China?', 'Quel empereur a commencé la construction d''un grand mur de « dix mille lieues » après l''unification de la Chine ?', '["Tang Taizong", "Han Wudi", "Qin Shi Huang", "Ming Yongle"]'::jsonb, '["Tang Taizong", "Han Wudi", "Qin Shi Huang", "Ming Yongle"]'::jsonb, 2, 'General Knowledge', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4758b27a8070048d', 'Which Roman dynasty is responsible for the name ''Flavian Amphitheatre'' given to the Colosseum?', 'Quelle dynastie romaine est à l''origine du nom ''amphithéâtre Flavien'' donné au Colisée ?', '["The Antonine dynasty", "The Flavian dynasty", "The Julio-Claudian dynasty", "The Severan dynasty"]'::jsonb, '["La dynastie des Antonins", "La dynastie flavienne", "La dynastie julio-claudienne", "La dynastie des Sévères"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8b9cc5055b9500fe', 'The Colosseum is depicted on the Italian 20-cent euro coin.', 'Le Colisée est représenté sur la pièce italienne de 20 centimes d''euro.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'General Knowledge', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-93e0c82dbe0e7579', 'Which military campaign funded the construction of the Colosseum?', 'Quelle campagne militaire a permis de financer la construction du Colisée ?', '["The First Jewish-Roman War", "The Punic Wars", "The Gallic Wars", "The conquest of Egypt"]'::jsonb, '["La première guerre judéo-romaine", "Les guerres puniques", "La guerre des Gaules", "La conquête de l''Égypte"]'::jsonb, 0, 'General Knowledge', 'hard', CURRENT_TIMESTAMP)
ON CONFLICT DO NOTHING;

